@import url('https://fonts.googleapis.com/css2?family=Poppins:wght@400;500;600;700&family=JetBrains+Mono:wght@400;500;600;700&display=swap');

/* Neumorphism — soft extruded gray surfaces, double shadows, pill shapes */
.theme-neumorphism {
  --bg: oklch(0.920 0.011 256.7);
  --surface: oklch(0.920 0.011 256.7);
  --surface-2: oklch(0.893 0.014 258.3);
  --fg: oklch(0.38 0.02 265);
  --fg-muted: oklch(0.58 0.02 265);
  --accent: oklch(0.62 0.14 265);
  --accent-fg: oklch(0.99 0 0);
  --accent-2: oklch(0.72 0.11 200);
  --line: oklch(1 0 0 / 0%);
  --success: oklch(0.68 0.14 155);
  --warning: oklch(0.78 0.14 80);
  --danger: oklch(0.62 0.19 22);

  --radius: 1.5rem;
  --radius-sm: 1rem;
  --radius-lg: 2rem;
  --radius-pill: 9999px;

  --shadow-1: 6px 6px 12px oklch(0.72 0.02 260 / 60%), -6px -6px 12px oklch(1 0 0 / 90%);
  --shadow-2: 10px 10px 20px oklch(0.72 0.02 260 / 55%), -10px -10px 20px oklch(1 0 0 / 90%);
  --shadow-3: 16px 16px 36px oklch(0.74 0.012 260 / 90%), -16px -16px 36px oklch(1 0 0 / 95%);
  --glow: inset 4px 4px 10px oklch(0.78 0.01 260 / 90%), inset -4px -4px 10px oklch(1 0 0 / 95%);

  --border-width: 0px;
  --blur-amount: 0px;

  --font-display: "Poppins", "Inter", sans-serif;
  --font-body: "Poppins", "Inter", sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;

  --tracking-display: -0.02em;
  --label-transform: uppercase;
  --label-tracking: 0.14em;

  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}

.theme-neumorphism h1,
.theme-neumorphism h2,
.theme-neumorphism h3 {
  font-family: var(--font-display);
  letter-spacing: var(--tracking-display);
  font-weight: 600;
}

.theme-neumorphism input,
.theme-neumorphism textarea,
.theme-neumorphism select {
  box-shadow: inset 4px 4px 8px oklch(0.8 0.01 260 / 90%), inset -4px -4px 8px oklch(1 0 0 / 95%);
}

/* signature */
.theme-neumorphism button:active { box-shadow: inset 3px 3px 6px oklch(0 0 0 / 15%), inset -3px -3px 6px oklch(1 0 0 / 90%); transform: none; }
.theme-neumorphism h1, .theme-neumorphism h2 { color: var(--fg); text-shadow: 1px 1px 1px oklch(1 0 0 / 80%); }

/* depth */
.theme-neumorphism thead th { color: var(--fg-muted); font-size: 0.7em; font-weight: 600; text-transform: uppercase; letter-spacing: 0.14em; border-bottom: none; box-shadow: 0 1px 0 oklch(0.78 0.015 260 / 70%), 0 2px 0 oklch(1 0 0 / 90%); }
.theme-neumorphism td { border-bottom: none; box-shadow: 0 1px 0 oklch(0.82 0.012 260 / 60%), 0 2px 0 oklch(1 0 0 / 85%); }
.theme-neumorphism tbody tr:hover { background: oklch(0.94 0.01 256); }
.theme-neumorphism input:focus-visible, .theme-neumorphism textarea:focus-visible, .theme-neumorphism select:focus-visible { outline: none; box-shadow: inset 4px 4px 8px oklch(0.8 0.01 260 / 90%), inset -4px -4px 8px oklch(1 0 0 / 95%), 0 0 0 3px oklch(0.62 0.14 265 / 30%); }
.theme-neumorphism kbd { background: var(--bg); border-radius: 0.5em; padding: 0.12em 0.5em; font-family: var(--font-mono); font-size: 0.85em; box-shadow: 3px 3px 6px oklch(0.74 0.02 260 / 60%), -3px -3px 6px oklch(1 0 0 / 90%); }
.theme-neumorphism a { color: var(--accent); text-decoration: none; font-weight: 600; }
.theme-neumorphism a:hover { text-decoration: underline; text-underline-offset: 0.25em; text-decoration-thickness: 2px; }
.theme-neumorphism ::selection { background: oklch(0.62 0.14 265 / 25%); }
.theme-neumorphism ::-webkit-scrollbar { width: 12px; height: 12px; }
.theme-neumorphism ::-webkit-scrollbar-track { background: var(--bg); box-shadow: inset 2px 2px 5px oklch(0.78 0.01 260 / 80%), inset -2px -2px 5px oklch(1 0 0 / 90%); border-radius: 9999px; }
.theme-neumorphism ::-webkit-scrollbar-thumb { background: oklch(0.86 0.012 258); border-radius: 9999px; box-shadow: 2px 2px 4px oklch(0.72 0.02 260 / 50%), -2px -2px 4px oklch(1 0 0 / 80%); }
.theme-neumorphism ::-webkit-scrollbar-thumb:hover { background: oklch(0.82 0.014 260); }
.theme-neumorphism .label-caps { color: var(--fg-muted); text-shadow: 1px 1px 1px oklch(1 0 0 / 85%); }
.theme-neumorphism .themed-border { border-color: transparent; box-shadow: var(--shadow-1); }
.theme-neumorphism button:hover { box-shadow: 8px 8px 16px oklch(0.72 0.02 260 / 60%), -8px -8px 16px oklch(1 0 0 / 95%); }

/* alt mode: charcoal clay — true dark neumorphism, light from the upper left */
.theme-neumorphism.alt-mode {
  --bg: oklch(0.245 0.014 258);
  --surface: oklch(0.245 0.014 258);
  --surface-2: oklch(0.275 0.014 258);
  --fg: oklch(0.86 0.01 258);
  --fg-muted: oklch(0.66 0.012 258);
  --line: oklch(1 0 0 / 0%);
  --shadow-1: 6px 6px 12px oklch(0.15 0.012 258 / 85%), -6px -6px 12px oklch(0.33 0.015 258 / 80%);
  --shadow-2: 10px 10px 20px oklch(0.14 0.012 258 / 85%), -10px -10px 20px oklch(0.34 0.015 258 / 80%);
  --shadow-3: 16px 16px 36px oklch(0.12 0.012 258 / 90%), -16px -16px 36px oklch(0.35 0.015 258 / 85%);
  --glow: inset 4px 4px 10px oklch(0.16 0.012 258 / 90%), inset -4px -4px 10px oklch(0.33 0.015 258 / 85%);
}
.theme-neumorphism.alt-mode input, .theme-neumorphism.alt-mode textarea, .theme-neumorphism.alt-mode select { box-shadow: inset 4px 4px 8px oklch(0.16 0.012 258 / 90%), inset -4px -4px 8px oklch(0.32 0.015 258 / 80%); }
.theme-neumorphism.alt-mode button:active { box-shadow: inset 3px 3px 6px oklch(0.12 0.012 258 / 90%), inset -3px -3px 6px oklch(0.32 0.015 258 / 80%); }
.theme-neumorphism.alt-mode button:hover { box-shadow: 8px 8px 16px oklch(0.14 0.012 258 / 85%), -8px -8px 16px oklch(0.34 0.015 258 / 80%); }
.theme-neumorphism.alt-mode h1, .theme-neumorphism.alt-mode h2 { text-shadow: 1px 1px 1px oklch(0.12 0.012 258 / 80%); }
.theme-neumorphism.alt-mode thead th { box-shadow: 0 1px 0 oklch(0.15 0.012 258 / 80%), 0 2px 0 oklch(0.32 0.015 258 / 60%); }
.theme-neumorphism.alt-mode td { box-shadow: 0 1px 0 oklch(0.16 0.012 258 / 70%), 0 2px 0 oklch(0.31 0.015 258 / 50%); }
.theme-neumorphism.alt-mode tbody tr:hover { background: oklch(0.27 0.014 258); }
.theme-neumorphism.alt-mode kbd { background: var(--bg); box-shadow: 3px 3px 6px oklch(0.15 0.012 258 / 80%), -3px -3px 6px oklch(0.33 0.015 258 / 75%); }
.theme-neumorphism.alt-mode ::-webkit-scrollbar-track { background: var(--bg); box-shadow: inset 2px 2px 5px oklch(0.16 0.012 258 / 85%), inset -2px -2px 5px oklch(0.32 0.015 258 / 75%); }
.theme-neumorphism.alt-mode ::-webkit-scrollbar-thumb { background: oklch(0.3 0.014 258); box-shadow: 2px 2px 4px oklch(0.15 0.012 258 / 70%), -2px -2px 4px oklch(0.34 0.015 258 / 60%); }
.theme-neumorphism.alt-mode .label-caps { text-shadow: 1px 1px 1px oklch(0.12 0.012 258 / 70%); }

/* Bridge shadcn semantic variables to the theme tokens so stock shadcn/ui
   components are skinned by the theme. Scope-safe: applies inside the theme
   class only. */
[class*="theme-"] {
  --background: var(--bg);
  --foreground: var(--fg);
  --card: var(--surface);
  --card-foreground: var(--fg);
  --popover: var(--surface);
  --popover-foreground: var(--fg);
  --primary: var(--accent);
  --primary-foreground: var(--accent-fg);
  --secondary: var(--surface-2);
  --secondary-foreground: var(--fg);
  --muted: var(--surface-2);
  --muted-foreground: var(--fg-muted);
  --accent-foreground: var(--accent-fg);
  --border: var(--line);
  --input: var(--line);
  --ring: var(--accent);
  --destructive: var(--danger);
  --destructive-foreground: var(--accent-fg);

  /* Full app surface: sidebar, charts, app-level font + shadow + tracking vars.
     These are what real products (shadcn full kit, RootCX-style UI kits) consume —
     without them a retrofit looks half-themed. */
  --sidebar: var(--surface-2);
  --sidebar-foreground: var(--fg);
  --sidebar-primary: var(--accent);
  --sidebar-primary-foreground: var(--accent-fg);
  --sidebar-accent: color-mix(in oklab, var(--accent) 12%, var(--surface-2));
  --sidebar-accent-foreground: var(--fg);
  --sidebar-border: var(--line);
  --sidebar-ring: var(--accent);

  --chart-1: var(--accent);
  --chart-2: var(--accent-2);
  --chart-3: var(--success);
  --chart-4: var(--warning);
  --chart-5: var(--danger);

  --font-sans: var(--font-body);
  --font-heading: var(--font-display);
  --font-serif: var(--font-display);

  --shadow-2xs: var(--shadow-1);
  --shadow-xs: var(--shadow-1);
  --shadow-sm: var(--shadow-1);
  --shadow: var(--shadow-2);
  --shadow-md: var(--shadow-2);
  --shadow-lg: var(--shadow-3);
  --shadow-xl: var(--shadow-3);
  --shadow-2xl: var(--shadow-3);

  --tracking-normal: 0em;
}

/* Base experience: make the theme own the canvas and native elements even in
   apps that never adopted semantic classes. Scoped to the theme wrapper. */
[class*="theme-"] {
  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}
[class*="theme-"] :is(h1, h2, h3, h4) { font-family: var(--font-display); }
[class*="theme-"] :is(code, pre, kbd, samp) { font-family: var(--font-mono); }
[class*="theme-"] ::selection { background: color-mix(in oklab, var(--accent) 30%, transparent); }
